      fg(`Rata-rata "${cut2(tr2.num, 22)}" per ${GRAN[tr2.gran] ?? tr2.gran}`, lineChart(tr2.labels, tr2.values, tr2.num));
      tb(`Ringkasan tren "${cut2(tr2.num, 20)}"`, ["Ukuran", "Nilai"], [
        ["Periode pengamatan", nf2(nT, 0)],
        ["Nilai awal", nf2(first)],
        ["Nilai akhir", nf2(last2)],
        ["Minimum", `${nf2(mn)} (${tr2.labels[tr2.values.indexOf(mn)]})`],
        ["Maksimum", `${nf2(mx)} (${tr2.labels[tr2.values.indexOf(mx)]})`],
        ["Kemiringan tren", nf2(slope, 4)],
        ["R\xB2 tren", nf2(r22, 3)]
      ], ["l", "r"]);
      const stp = Math.max(1, Math.ceil(nT / 8));
      const idx = [];
      for (let i = 0; i < nT; i += stp) {
        idx.push(i);
      }
      if (idx[idx.length - 1] !== nT - 1) {
        idx.push(nT - 1);
      }
      tb(`Rata-rata "${cut2(tr2.num, 24)}" per ${GRAN[tr2.gran] ?? tr2.gran}`, ["Periode", "Rata-rata"], idx.map((i) => [tr2.labels[i], nf2(tr2.values[i])]), ["l", "r"]);
