  widths(wsW, [6, 36, 70, 16]);
  title(wsW, "Diagram Alir Analisis (merah = jalur utama, biru = cabang aktif, abu-abu = dilewati)");
  hdr(wsW.addRow(["No", "Langkah", "Hasil utama", "Status"]));
  const stTxt = { critical: "Jalur utama", active: "Cabang aktif", skipped: "Dilewati" };
  const stCol = { critical: "FFC00000", active: BLUE2, skipped: "FF7F7F7F" };
  fc.rows.forEach((r) => {
    const row2 = wsW.addRow([r.no, r.step, r.result, stTxt[r.state]]);
    row2.eachCell((c) => {
      c.border = BORDER;
    });
    row2.getCell(4).font = { bold: true, color: { argb: stCol[r.state] } };
  });
  wsW.addRow([]);
  below(wsW, "Diagram alir analisis data otomatis", flowChart(fc), 1100);
  const wsG = wb.addWorksheet("Grafik", { properties: { tabColor: { argb: "FFED7D31" } } });
  widths(wsG, [4, 100]);
  let row = 1;
  gallery.forEach((c, i) => {
    wsG.getCell(`A${row}`).value = `Gambar ${i + 1}. ${c.name}`;
    wsG.getCell(`A${row}`).font = { bold: true, color: { argb: BLUE2 } };
    const h = putImg(wsG, c.ch, 0, row, 600);
    row += Math.ceil(h / 20) + 3;
  });
  if (!gallery.length) {
    wsG.getCell("A1").value = "Tidak ada grafik yang dapat dibuat dari data ini.";
  }
