        const actions = format === "easycastPdf" ? [tr("Buka File", "\u6253\u5F00\u6587\u4EF6"), tr("Cetak di browser", "\u5728\u6D4F\u89C8\u5668\u4E2D\u6253\u5370")] : [tr("Buka File", "\u6253\u5F00\u6587\u4EF6")];
