  lines.push(`RAM     : ${formatBytes2(m.memTotal - m.memFree)} / ${formatBytes2(m.memTotal)} terpakai (${m.memUsedPct}%)`);
  lines.push(`          sisa ${formatBytes2(m.memFree)}`);
