      at: Date.now(),
      name: (opts.name || this.pickPartner()).slice(0, 24),
      role: "partner",
      text: String(text2 || "").trim().slice(0, MAX_TEXT2) || "\u2014",
      symbol: opts.symbol,
      signal: opts.signal,
      verdict: opts.verdict,
      topic: opts.topic
