  const side = buyPass ? "BUY" : sellPass ? "SELL" : "HOLD";
  const checks = side === "SELL" ? sell : buy;
  const total = checks.length;
  const passed = checks.filter((c) => c.pass).length;
  const weightAll = checks.reduce((a, c) => a + c.weight, 0) || 1;
  const weightPass = checks.filter((c) => c.pass).reduce((a, c) => a + c.weight, 0);
  const score = Math.round(weightPass / weightAll * 100);
