  const aturan = c.verdict === "TUNGGU" ? "DILARANG menyarankan BUY/SELL. Wajib SINYAL: HOLD, sebut syarat yang belum lulus, dan sarankan menunggu." : `Boleh menyebut ${c.side}. Level WAJIB entry ${c.entry} / stop ${c.stop} / TP1 ${c.tp1} / TP2 ${c.tp2} / R:R 1:${c.rr}.`;
