  // ── konsol ───────────────────────────────────────────────────────────────
  async runCommand(raw) {
    const line3 = String(raw || "").trim();
    if (!line3) {
      return;
    }
    this.log(`mt> ${line3}`, "cmd");
    const [cmdRaw, ...rest] = line3.split(/\s+/);
    const cmd = cmdRaw.toLowerCase();
    const arg = rest.join(" ").trim();
    if (cmd === "help" || cmd === "?") {
      this.log([
        "Perintah konsol MetaTrader AI:",
        "  connect | disconnect   sambungkan / putuskan jembatan",
        "  symbol <kode>          ganti simbol (mis. XAUUSD)",
        "  tf <M1|M5|M15|H1|H4>   ganti timeframe",
        "  analisa                minta rencana AI + validasi",
        "  eksekusi               kirim order (setelah konfirmasi)",
        "  posisi                 daftar posisi",
        "  tutup <tiket>          tutup satu posisi",
        "  tutup semua            tutup semua posisi",
        "  models | pilih <n>     daftar/pilih model .gguf",
        "  start | stop           nyalakan / hentikan llama-server",
        "  server                 terminal log llama-server",
        "  status                 keadaan akun & rencana"
      ].join("\n"), "out");
      return;
    }
    if (cmd === "connect") {
      this.autoPaused = false;
      await this.ensureConnected(true);
      return;
    }
    if (cmd === "disconnect") {
      await this.onMessage({ type: "disconnect" });
      return;
    }
    if (cmd === "symbol") {
      await this.onMessage({ type: "symbol", symbol: arg });
      return;
    }
    if (cmd === "tf" || cmd === "timeframe") {
      await this.onMessage({ type: "timeframe", timeframe: arg });
      return;
    }
    if (cmd === "analisa" || cmd === "analyze") {
      await this.analyze();
      return;
    }
    if (cmd === "eksekusi" || cmd === "execute") {
      await this.execute();
      return;
    }
    if (cmd === "posisi" || cmd === "positions") {
      await this.refreshPositions();
      this.log(`${this.positions.length} posisi terbuka.`, "out");
      return;
    }
    if (cmd === "tutup" || cmd === "close") {
      if (arg === "semua" || arg === "all") {
        await this.closeAll();
        return;
      }
      await this.closePosition(Number(arg) || 0);
      return;
    }
    if (cmd === "models") {
      let list = this.ai.models;
      if (!list.length) {
        await this.ai.listModels({ deep: true, force: true });
        list = this.ai.models;
      }
      this.log(list.length ? ["Model .gguf:", ...list.slice(0, 30).map((x, i) => `  ${String(i + 1).padStart(2)}. ${x.name} \xB7 ${x.size}${x.path === this.ai.config().modelPath ? "  \u2190 dipakai" : ""}`)].join("\n") : "Belum ada berkas .gguf.", list.length ? "out" : "err");
      return;
    }
    if (cmd === "pilih" || cmd === "pakai") {
      const n = Number(arg);
      const list = this.ai.models;
      if (!isFinite(n) || n < 1 || n > list.length) {
        this.log(`Nomor tidak dikenal. Tulis \u201Cmodels\u201D.`, "err");
        return;
      }
      await this.ai.setModel(list[n - 1].path);
      this.postModels();
      this.post({ type: "ai", ai: this.aiState() });
      this.log(`Model \u2192 ${list[n - 1].name}`, "ok");
      return;
    }
    if (cmd === "start") {
      await this.onMessage({ type: "server", action: "start" });
      return;
    }
    if (cmd === "stop") {
      await this.onMessage({ type: "server", action: "stop" });
      return;
    }
    if (cmd === "server") {
      this.showServerTerminal();
      return;
    }
    if (cmd === "status") {
      const s = readSettings();
      this.log([
        `Simbol     : ${this.symbol} ${this.timeframe}`,
        `Jembatan   : ${this.health ? `${this.health.mode} \xB7 ${this.health.platform}` : "belum terhubung"}`,
        `Akun       : ${this.account ? `${fmt3(this.account.balance)} ${this.account.currency || ""} \xB7 ekuitas ${fmt3(this.account.equity)}` : "-"}`,
        `Quote      : ${this.quote ? `bid ${fmt3(this.quote.bid, this.quote.digits)} / ask ${fmt3(this.quote.ask, this.quote.digits)} \xB7 spread ${this.quote.spread}` : "-"}`,
        `ATR/RSI    : ${fmt3(this.atrVal, 5)} / ${this.rsiVal === null ? "-" : this.rsiVal.toFixed(1)}`,
        `Rencana    : ${this.plan ? `${this.plan.action} ${this.plan.ok ? "LOLOS" : "DITOLAK"} \xB7 lot ${this.plan.lot} \xB7 R:R 1:${this.plan.rr}` : "-"}`,
        `Risiko     : ${s.riskPercent}% ekuitas \xB7 R:R min ${s.minRR} \xB7 keyakinan min ${s.minConfidence}% \xB7 auto-trade ${s.autoTrade ? "AKTIF" : "mati"}`,
        `Posisi     : ${this.positions.length}`
      ].join("\n"), "out");
      return;
    }
    this.log(`Perintah "${cmd}" tidak dikenal. Tulis "help".`, "err");
  }
