function registerMtView(context) {
  const provider = new MtViewProvider(context);
  context.subscriptions.push(
    vscode23.window.registerWebviewViewProvider(VIEW_ID3, provider, { webviewOptions: { retainContextWhenHidden: true } }),
    vscode23.commands.registerCommand("date-skunder.mt.open", async () => provider.focus()),
    vscode23.commands.registerCommand("date-skunder.mt.connect", async () => {
      await provider.focus();
      void provider.command("connect");
    }),
    vscode23.commands.registerCommand("date-skunder.mt.analyze", async () => {
      await provider.focus();
      void provider.command("analyze");
    }),
    vscode23.commands.registerCommand("date-skunder.mt.models", async () => provider.pickModel()),
    vscode23.commands.registerCommand("date-skunder.mt.serverTerminal", () => provider.showServerTerminal()),
    vscode23.commands.registerCommand("date-skunder.mt.bridgeTerminal", () => provider.showBridgeTerminal()),
    vscode23.commands.registerCommand("date-skunder.mt.closeAll", async () => {
      await provider.focus();
      void provider.command("closeAll");
    }),
    { dispose: () => provider.dispose() }
  );
  return provider;
}

